    "content": "{\n  \"name\": \"ai-architecture-design\",\n  \"version\": \"0.1.0\",\n  \"description\": \"AI-powered architecture and interior design platform with Vastu optimization\",\n  \"private\": true,\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"next start\",\n    \"lint\": \"next lint\",\n    \"type-check\": \"tsc --noEmit\",\n    \"format\": \"prettier --write \\\"src/**/*.{ts,tsx,json,css,md}\\\"\"\n  },\n  \"dependencies\": {\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"next\": \"^14.0.0\",\n    \"typescript\": \"^5.3.0\",\n    \"tailwindcss\": \"^3.3.0\",\n    \"framer-motion\": \"^10.16.0\",\n    \"zustand\": \"^4.4.0\",\n    \"axios\": \"^1.6.0\",\n    \"openai\": \"^4.20.0\",\n    \"@anthropic-ai/sdk\": \"^0.9.0\",\n    \"three\": \"^r158\",\n    \"react-three-fiber\": \"^8.14.0\",\n    \"@react-three/drei\": \"^9.88.0\",\n    \"sharp\": \"^0.32.0\",\n    \"next-auth\": \"^4.24.0\",\n    \"@supabase/supabase-js\": \"^2.38.0\",\n    \"lucide-react\": \"^0.292.0\",\n    \"clsx\": \"^2.0.0\",\n    \"tailwind-merge\": \"^2.2.0\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^18.2.0\",\n    \"@types/react-dom\": \"^18.2.0\",\n    \"@types/node\": \"^20.0.0\",\n    \"@types/three\": \"^r158\",\n    \"autoprefixer\": \"^10.4.0\",\n    \"postcss\": \"^8.4.0\",\n    \"prettier\": \"^3.0.0\",\n    \"eslint\": \"^8.50.0\",\n    \"eslint-config-next\": \"^14.0.0\"\n  },\n  \"engines\": {\n    \"node\": \">=18.0.0\"\n  }\n}\n"
  },
  {
    "path": "tsconfig.json",
    "content": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"useDefineForClassFields\": true,\n    \"lib\": [\"ES2020\", \"DOM\", \"DOM.Iterable\"],\n    \"module\": \"ESNext\",\n    \"skipLibCheck\": true,\n    \"esModuleInterop\": true,\n    \"allowSyntheticDefaultImports\": true,\n    \"strict\": true,\n    \"noImplicitAny\": true,\n    \"strictNullChecks\": true,\n    \"strictFunctionTypes\": true,\n    \"strictBindCallApply\": true,\n    \"strictPropertyInitialization\": true,\n    \"noImplicitThis\": true,\n    \"alwaysStrict\": true,\n    \"noUnusedLocals\": true,\n    \"noUnusedParameters\": true,\n    \"noImplicitReturns\": true,\n    \"noFallthroughCasesInSwitch\": true,\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"noEmit\": true,\n    \"jsx\": \"react-jsx\",\n    \"baseUrl\": \".\",\n    \"paths\": {\n      \"@/*\": [\"./src/*\"]\n    }\n  },\n  \"include\": [\"src\"],\n  \"exclude\": [\"node_modules\"]\n}\n"
  },
  {
    "path": "tailwind.config.ts",
    "content": "import type { Config } from 'tailwindcss'\n\nconst config: Config = {\n  content: [\n    './src/pages/**/*.{js,ts,jsx,tsx,mdx}',\n    './src/components/**/*.{js,ts,jsx,tsx,mdx}',\n    './src/app/**/*.{js,ts,jsx,tsx,mdx}',\n  ],\n  theme: {\n    extend: {\n      colors: {\n        black: '#000000',\n        white: '#FFFFFF',\n        gold: '#D4AF37',\n        'gold-light': '#E8C547',\n        'gold-dark': '#B8941E',\n        platinum: '#E0E0E0',\n        'dark-bg': '#0A0A0A',\n        'dark-card': '#1A1A1A',\n      },\n      fontFamily: {\n        serif: ['Playfair Display', 'serif'],\n        sans: ['Poppins', 'sans-serif'],\n      },\n      fontSize: {\n        'display-lg': ['72px', { lineHeight: '86px', fontWeight: '900' }],\n        'display-md': ['56px', { lineHeight: '67px', fontWeight: '800' }],\n        'heading-lg': ['48px', { lineHeight: '58px', fontWeight: '700' }],\n        'heading-md': ['32px', { lineHeight: '39px', fontWeight: '700' }],\n      },\n      backdropBlur: {\n        xs: '2px',\n      },\n      animation: {\n        'fade-in': 'fadeIn 0.5s ease-in-out',\n        'slide-up': 'slideUp 0.5s ease-out',\n        'glow': 'glow 3s ease-in-out infinite',\n      },\n      keyframes: {\n        fadeIn: {\n          '0%': { opacity: '0' },\n          '100%': { opacity: '1' },\n        },\n        slideUp: {\n          '0%': {\n            opacity: '0',\n            transform: 'translateY(20px)',\n          },\n          '100%': {\n            opacity: '1',\n            transform: 'translateY(0)',\n          },\n        },\n        glow: {\n          '0%, 100%': {\n            boxShadow: '0 0 20px rgba(212, 175, 55, 0.5)',\n          },\n          '50%': {\n            boxShadow: '0 0 30px rgba(212, 175, 55, 0.8)',\n          },\n        },\n      },\n    },\n  },\n  plugins: [],\n}\n\nexport default config\n"
  },
  {
