    "content": "/** @type {import('next').NextConfig} */\nconst nextConfig = {\n  images: {\n    remotePatterns: [\n      {\n        protocol: 'https',\n        hostname: '**',\n      },\n    ],\n    unoptimized: false,\n  },\n  reactStrictMode: true,\n  swcMinify: true,\n  experimental: {\n    optimizePackageImports: ['framer-motion', 'lucide-react'],\n  },\n}\n\nmodule.exports = nextConfig\n"
