    "content": "{\n  \"extends\": \"next/core-web-vitals\",\n  \"rules\": {\n    \"react/display-name\": \"off\",\n    \"@next/next/no-img-element\": \"off\"\n  }\n}\n"
  },\n  {
    "path\": \".env.example\",\n    \"content\": \"# OpenAI API\nNEXT_PUBLIC_OPENAI_API_KEY=sk_your_key_here\n\n# Anthropic Claude\nNEXT_PUBLIC_ANTHROPIC_API_KEY=sk_your_key_here\n\n# Supabase\nNEXT_PUBLIC_SUPABASE_URL=https://your-project.supabase.co\nNEXT_PUBLIC_SUPABASE_ANON_KEY=your_anon_key_here\nSUPABASE_SERVICE_ROLE_KEY=your_service_role_key_here\n\n# NextAuth\nNEXTAUTH_SECRET=your_secret_here\nNEXTAUTH_URL=http://localhost:3000\n\n# App Settings\nNEXT_PUBLIC_APP_NAME=AI Architecture Design Platform\nNEXT_PUBLIC_APP_URL=http://localhost:3000\n\"\n  },\n  {\n    \"path\": \".gitignore\",\n    \"content\": \"# Dependencies\nnode_modules/\n.pnp\n.pnp.js\n\n# Testing\ncoverage/\n\n# Production\nbuild/\n.next/\nout/\ndist/\n\n# Misc\n.DS_Store\n*.pem\n*.log\nnpm-debug.log*\nyarn-debug.log*\nyarn-error.log*\n\n# Debug\n.vscode/\n.idea/\n*.swp\n*.swo\n*~\n\n# Local env files\n.env\n.env.local\n.env.*.local\n\n# IDE\n.vscode/\n.idea/\n*.iml\n\"\n  },\n  {\n    \"path\": \"src/app/layout.tsx\",\n    \"content\": \"import type { Metadata } from 'next'\nimport './globals.css'\n\nexport const metadata: Metadata = {\n  title: 'AI Architecture Design Platform',\n  description: 'Advanced AI-powered architecture and interior design platform with Vastu optimization',\n  keywords: 'architecture, design, AI, luxury, Vastu, interior design',\n  viewport: 'width=device-width, initial-scale=1',\n  robots: 'index, follow',\n}\n\nexport default function RootLayout({\n  children,\n}: {\n  children: React.ReactNode\n}) {\n  return (\n    <html lang=\\\"en\\\">\n      <head>\n        <link rel=\\\"preconnect\\\" href=\\\"https://fonts.googleapis.com\\\" />\n        <link rel=\\\"preconnect\\\" href=\\\"https://fonts.gstatic.com\\\" />\n        <link\n          href=\\\"https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800&family=Playfair+Display:wght@700;900&display=swap\\\"\n          rel=\\\"stylesheet\\\"\n        />\n      </head>\n      <body className=\\\"bg-black text-white\\\">\n        <div className=\\\"relative\\\">\n          {children}\n        </div>\n      </body>\n    </html>\n  )\n}\n\"\n  },\n  {\n    \"path\": \"src/app/globals.css\",\n    \"content\": \"@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu',\n    'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  background: #000;\n  color: #fff;\n  overflow-x: hidden;\n}\n\n::-webkit-scrollbar {\n  width: 10px;\n}\n\n::-webkit-scrollbar-track {\n  background: #1a1a1a;\n}\n\n::-webkit-scrollbar-thumb {\n  background: #D4AF37;\n  border-radius: 5px;\n}\n\n::-webkit-scrollbar-thumb:hover {\n  background: #E8C547;\n}\n\n.text-gold-gradient {\n  background: linear-gradient(135deg, #D4AF37 0%, #E8C547 50%, #D4AF37 100%);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  background-clip: text;\n}\n\n.shadow-luxury {\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8);\n}\n\n.glow-gold {\n  box-shadow: 0 0 20px rgba(212, 175, 55, 0.5);\n}\n\n.transition-smooth {\n  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\nbutton {\n  transition: all 0.3s ease;\n}\n\nbutton:hover {\n  transform: translateY(-2px);\n}\n\"\n  },\n  {\n    \"path\": \"src/app/page.tsx\",\n    \"content\": \"'use client'\n\nimport { motion } from 'framer-motion'\nimport Link from 'next/link'\nimport { ArrowRight, Sparkles, Zap, Brain, Palette, Home, Compass } from 'lucide-react'\n\nconst fadeInUp = {\n  initial: { opacity: 0, y: 20 },\n  animate: { opacity: 1, y: 0 },\n  transition: { duration: 0.6 },\n}\n\nconst staggerContainer = {\n  animate: {\n    transition: {\n      staggerChildren: 0.1,\n      delayChildren: 0.3,\n    },\n  },\n}\n\nconst features = [\n  {\n    icon: Brain,\n    title: 'AI Architect Guru',\n    description: 'Conversational AI assistant for architectural guidance and design recommendations',\n  },\n  {\n    icon: Sparkles,\n    title: 'Multi-Concept Generation',\n    description: 'Generate 5 to 100+ unique architectural concepts powered by AI',\n  },\n  {\n    icon: Palette,\n    title: 'Smart Color & Material AI',\n    description: 'Intelligent material palettes and color combinations for luxury design',\n  },\n  {\n    icon: Compass,\n    title: 'Vastu Optimization',\n    description: 'Harmonize designs with Vastu principles and cultural aesthetics',\n  },\n  {\n    icon: Home,\n    title: 'Global Style Selection',\n    description: 'Choose from global architectural styles and luxury concepts',\n  },\n  {\n    icon: Zap,\n    title: 'Real-Time Rendering',\n    description: 'Instant visual previews of your architectural designs',\n  },\n]\n\nexport default function Home() {\n  return (\n    <main className=\\\"bg-black text-white overflow-hidden\\\">\n      {/* Navigation */}\n      <nav className=\\\"fixed top-0 w-full z-50 backdrop-blur-md bg-black/50 border-b border-gold/20\\\">\n        <div className=\\\"max-w-7xl mx-auto px-6 py-4 flex justify-between items-center\\\">\n          <motion.div\n            initial={{ opacity: 0 }}\n            animate={{ opacity: 1 }}\n            className=\\\"text-2xl font-bold text-gold font-serif\\\"\n          >\n            AI Architect\n          </motion.div>\n          <div className=\\\"flex gap-4\\\">\n            <Link\n              href=\\\"/dashboard\\\"\n              className=\\\"px-6 py-2 rounded-lg border border-gold text-gold hover:bg-gold/10 transition-colors\\\"\n            >\n              Dashboard\n            </Link>\n          </div>\n        </div>\n      </nav>\n\n      {/* Hero Section */}\n      <section className=\\\"pt-32 pb-20 px-6 relative overflow-hidden\\\">\n        <div className=\\\"absolute inset-0 overflow-hidden\\\">\n          <div className=\\\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-gold/20 rounded-full blur-3xl opacity-20\\\" />\n        </div>\n\n        <motion.div\n          className=\\\"max-w-4xl mx-auto text-center relative z-10\\\"\n          variants={staggerContainer}\n          initial=\\\"initial\\\"\n          animate=\\\"animate\\\"\n        >\n          <motion.div variants={fadeInUp} className=\\\"mb-6\\\">\n            <span className=\\\"inline-block px-4 py-2 rounded-full bg-gold/10 border border-gold/30 text-gold text-sm font-semibold\\\">✨ Powered by Advanced AI</span>\n          </motion.div>\n\n          <motion.h1\n            variants={fadeInUp}\n            className=\\\"text-6xl md:text-7xl font-bold font-serif mb-6 leading-tight\\\"\n          >\n            Design Your <span className=\\\"text-gold-gradient\\\">Dream Home</span> with AI\n          </motion.h1>\n\n          <motion.p\n            variants={fadeInUp}\n            className=\\\"text-xl text-platinum mb-8 max-w-2xl mx-auto\\\"\n          >\n            Intelligent architecture platform combining luxury design, Vastu optimization, and global design inspiration with real-time AI assistance\n          </motion.p>\n\n          <motion.div variants={fadeInUp} className=\\\"flex gap-4 justify-center flex-wrap\\\">\n            <Link\n              href=\\\"/dashboard\\\"\n              className=\\\"px-8 py-4 rounded-lg bg-gold text-black font-bold hover:bg-gold-light transition-all flex items-center gap-2 shadow-luxury hover:shadow-lg\\\"\n            >\n              Launch Studio <ArrowRight className=\\\"w-5 h-5\\\" />\n            </Link>\n            <button className=\\\"px-8 py-4 rounded-lg border-2 border-gold text-gold hover:bg-gold/10 font-bold transition-all\\\">Learn More</button>\n          </motion.div>\n        </motion.div>\n      </section>\n\n      {/* Features Section */}\n      <section className=\\\"py-20 px-6\\\">\n        <div className=\\\"max-w-6xl mx-auto\\\">\n          <motion.div\n            initial={{ opacity: 0 }}\n            whileInView={{ opacity: 1 }}\n            transition={{ duration: 0.6 }}\n            className=\\\"text-center mb-16\\\"\n          >\n            <h2 className=\\\"text-4xl md:text-5xl font-bold font-serif mb-4\\\">Powerful Features</h2>\n            <p className=\\\"text-platinum text-lg\\\">Everything you need to create luxury architectural designs</p>\n          </motion.div>\n\n          <motion.div\n            className=\\\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6\\\"\n            variants={staggerContainer}\n            initial=\\\"initial\\\"\n            whileInView=\\\"animate\\\"\n            viewport={{ once: true }}\n          >\n            {features.map((feature, index) => {\n              const Icon = feature.icon\n              return (\n                <motion.div\n                  key={index}\n                  variants={fadeInUp}\n                  className=\\\"p-8 rounded-xl bg-dark-card border border-gold/20 hover:border-gold/50 hover:bg-gold/5 transition-all group\\\"\n                >\n                  <Icon className=\\\"w-10 h-10 text-gold mb-4 group-hover:scale-110 transition-transform\\\" />\n                  <h3 className=\\\"text-xl font-bold mb-3\\\">{feature.title}</h3>\n                  <p className=\\\"text-platinum text-sm leading-relaxed\\\">{feature.description}</p>\n                </motion.div>\n              )\n            })}\n          </motion.div>\n        </div>\n      </section>\n\n      {/* CTA Section */}\n      <section className=\\\"py-20 px-6 bg-gradient-to-r from-gold/10 via-black to-gold/5 border-t border-b border-gold/20\\\">\n        <motion.div\n          initial={{ opacity: 0, y: 20 }}\n          whileInView={{ opacity: 1, y: 0 }}\n          transition={{ duration: 0.6 }}\n          className=\\\"max-w-3xl mx-auto text-center\\\"\n        >\n          <h2 className=\\\"text-4xl font-bold font-serif mb-6\\\">Ready to Create Magic?</h2>\n          <p className=\\\"text-platinum text-lg mb-8\\\">Start generating unlimited architectural concepts powered by AI</p>\n          <Link\n            href=\\\"/dashboard\\\"\n            className=\\\"inline-block px-8 py-4 rounded-lg bg-gold text-black font-bold hover:bg-gold-light transition-all shadow-luxury\\\"\n          >\n            Get Started Now\n          </Link>\n        </motion.div>\n      </section>\n\n      {/* Footer */}\n      <footer className=\\\"border-t border-gold/20 py-8 px-6\\\">\n        <div className=\\\"max-w-6xl mx-auto flex justify-between items-center text-platinum text-sm\\\">\n          <p>&copy; 2026 AI Architecture Design Platform. All rights reserved.</p>\n          <div className=\\\"flex gap-6\\\">\n            <a href=\\\"#\\\" className=\\\"hover:text-gold transition-colors\\\">Privacy</a>\n            <a href=\\\"#\\\" className=\\\"hover:text-gold transition-colors\\\">Terms</a>\n            <a href=\\\"#\\\" className=\\\"hover:text-gold transition-colors\\\">Contact</a>\n          </div>\n        </div>\n      </footer>\n    </main>\n  )\n}\n\"\n  },\n  {\n    \"path\": \"src/app/dashboard/page.tsx\",\n    \"content\": \"'use client'\n\nimport { motion } from 'framer-motion'\nimport Link from 'next/link'\nimport { ArrowLeft, Plus, Zap, Upload, Settings, BarChart3 } from 'lucide-react'\n\nexport default function Dashboard() {\n  return (\n    <main className=\\\"min-h-screen bg-black\\\">\n      {/* Header */}\n      <header className=\\\"border-b border-gold/20 bg-black/50 backdrop-blur-md sticky top-0 z-40\\\">\n        <div className=\\\"max-w-7xl mx-auto px-6 py-4 flex justify-between items-center\\\">\n          <Link href=\\\"/\\\" className=\\\"flex items-center gap-2 text-gold hover:text-gold-light transition-colors\\\">\n            <ArrowLeft className=\\\"w-5 h-5\\\" />\n            Back\n          </Link>\n          <h1 className=\\\"text-2xl font-bold\\\">Design Studio</h1>\n          <button className=\\\"p-2 rounded-lg hover:bg-gold/10 transition-colors\\\">\n            <Settings className=\\\"w-6 h-6 text-gold\\\" />\n          </button>\n        </div>\n      </header>\n\n      {/* Main Content */}\n      <div className=\\\"max-w-7xl mx-auto px-6 py-12\\\">\n        <motion.div\n          initial={{ opacity: 0, y: 20 }}\n          animate={{ opacity: 1, y: 0 }}\n          className=\\\"text-center mb-12\\\"\n        >\n          <h2 className=\\\"text-4xl font-bold mb-4\\\">Welcome to Your Design Studio</h2>\n          <p className=\\\"text-xl text-platinum\\\">\n            Start creating amazing architectural designs powered by AI\n          </p>\n        </motion.div>\n\n        {/* Quick Actions Grid */}\n        <motion.div\n          initial={{ opacity: 0 }}\n          animate={{ opacity: 1 }}\n          transition={{ delay: 0.2 }}\n          className=\\\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-12\\\"\n        >\n          {/* New Design */}\n          <motion.button\n            whileHover={{ scale: 1.05 }}\n            className=\\\"group p-8 rounded-xl border-2 border-gold/30 hover:border-gold hover:bg-gold/10 transition-all text-left\\\"\n          >\n            <Plus className=\\\"w-8 h-8 text-gold mb-4 group-hover:scale-110 transition-transform\\\" />\n            <h3 className=\\\"text-xl font-bold mb-2\\\">New Design Project</h3>\n            <p className=\\\"text-platinum\\\">Start a fresh architectural design concept</p>\n          </motion.button>\n\n          {/* AI Guru Chat */}\n          <motion.button\n            whileHover={{ scale: 1.05 }}\n            className=\\\"group p-8 rounded-xl border-2 border-gold/30 hover:border-gold hover:bg-gold/10 transition-all text-left\\\"\n          >\n            <Zap className=\\\"w-8 h-8 text-gold mb-4 group-hover:scale-110 transition-transform\\\" />\n            <h3 className=\\\"text-xl font-bold mb-2\\\">AI Architect Guru</h3>\n            <p className=\\\"text-platinum\\\">Chat with your AI design assistant</p>\n          </motion.button>\n\n          {/* Upload Image */}\n          <motion.button\n            whileHover={{ scale: 1.05 }}\n            className=\\\"group p-8 rounded-xl border-2 border-gold/30 hover:border-gold hover:bg-gold/10 transition-all text-left\\\"\n          >\n            <Upload className=\\\"w-8 h-8 text-gold mb-4 group-hover:scale-110 transition-transform\\\" />\n            <h3 className=\\\"text-xl font-bold mb-2\\\">Upload & Analyze</h3>\n            <p className=\\\"text-platinum\\\">Upload plot/sketch for AI analysis</p>\n          </motion.button>\n\n          {/* Generate Concepts */}\n          <motion.button\n            whileHover={{ scale: 1.05 }}\n            className=\\\"group p-8 rounded-xl border-2 border-gold/30 hover:border-gold hover:bg-gold/10 transition-all text-left\\\"\n          >\n            <BarChart3 className=\\\"w-8 h-8 text-gold mb-4 group-hover:scale-110 transition-transform\\\" />\n            <h3 className=\\\"text-xl font-bold mb-2\\\">Generate Concepts</h3>\n            <p className=\\\"text-platinum\\\">Generate multiple design variations</p>\n          </motion.button>\n\n          {/* 3D Viewer */}\n          <motion.button\n            whileHover={{ scale: 1.05 }}\n            className=\\\"group p-8 rounded-xl border-2 border-gold/30 hover:border-gold hover:bg-gold/10 transition-all text-left\\\"\n          >\n            <div className=\\\"w-8 h-8 bg-gradient-to-br from-gold to-gold-light rounded mb-4\\\" />\n            <h3 className=\\\"text-xl font-bold mb-2\\\">3D Visualization</h3>\n            <p className=\\\"text-platinum\\\">View interactive 3D design previews</p>\n          </motion.button>\n\n          {/* My Projects */}\n          <motion.button\n            whileHover={{ scale: 1.05 }}\n            className=\\\"group p-8 rounded-xl border-2 border-gold/30 hover:border-gold hover:bg-gold/10 transition-all text-left\\\"\n          >\n            <div className=\\\"w-8 h-8 text-gold mb-4\\\">\n              <svg fill=\\\"currentColor\\\" viewBox=\\\"0 0 24 24\\\">\n                <path d=\\\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z\\\" />\n              </svg>\n            </div>\n            <h3 className=\\\"text-xl font-bold mb-2\\\">My Projects</h3>\n            <p className=\\\"text-platinum\\\">View and manage saved designs</p>\n          </motion.button>\n        </motion.div>\n\n        {/* Under Development Message */}\n        <motion.div\n          initial={{ opacity: 0, scale: 0.95 }}\n          animate={{ opacity: 1, scale: 1 }}\n          transition={{ delay: 0.4 }}\n          className=\\\"text-center p-12 rounded-xl bg-gold/5 border border-gold/30\\\"\n        >\n          <h3 className=\\\"text-2xl font-bold mb-4\\\">🚀 Dashboard Under Development</h3>\n          <p className=\\\"text-platinum mb-6 max-w-2xl mx-auto\\\">We're building an incredible AI-powered design experience. Coming soon:</p>\n          <div className=\\\"grid grid-cols-1 md:grid-cols-2 gap-4 max-w-2xl mx-auto text-left mb-8\\\">\n            <div className=\\\"flex items-center gap-3\\\">\n              <span className=\\\"w-2 h-2 bg-gold rounded-full\\\" />\n              <span>AI Design Canvas</span>\n            </div>\n            <div className=\\\"flex items-center gap-3\\\">\n              <span className=\\\"w-2 h-2 bg-gold rounded-full\\\" />\n              <span>Multi-Concept Generator</span>\n            </div>\n            <div className=\\\"flex items-center gap-3\\\">\n              <span className=\\\"w-2 h-2 bg-gold rounded-full\\\" />\n              <span>3D Visualization</span>\n            </div>\n            <div className=\\\"flex items-center gap-3\\\">\n              <span className=\\\"w-2 h-2 bg-gold rounded-full\\\" />\n              <span>Vastu Analysis</span>\n            </div>\n          </div>\n          <Link\n            href=\\\"/\\\"\n            className=\\\"inline-flex items-center px-6 py-3 rounded-lg bg-gold text-black font-bold hover:bg-gold-light transition-colors\\\"\n          >\n            Back to Home\n          </Link>\n        </motion.div>\n      </div>\n    </main>\n  )\n}\n\"\n  },\n  {\n    \"path\": \"README.md\",\n    \"content\": \"# AI Architecture Design Platform\\n\\n🏢 **Advanced AI-powered architecture and interior design platform with Vastu optimization, global style selection, and luxury design intelligence.**\\n\\n## 🌟 Features\\n\\n### 🤖 AI Architect Guru\\n- Conversational AI assistant for architectural guidance\\n- Answer design questions and provide recommendations\\n- Vastu optimization suggestions\\n- Material and color recommendations\\n\\n### ✨ Multi-Concept Generation\\n- Generate 5, 10, 25, 50, 100+ unique architectural concepts\\n- Unlimited inspiration mode\\n- Structurally practical designs\\n- Vastu-optimized layouts\\n\\n### 🌍 Global Style Selection\\n- Indian luxury homes\\n- Dubai mansions\\n- Japanese minimalist\\n- Scandinavian interiors\\n- Mediterranean villas\\n- And many more...\\n\\n### 🎨 Smart Color & Material AI\\n- Intelligent material palettes\\n- Harmonious color combinations\\n- Luxury theme generation\\n- Customizable aesthetics\\n\\n### 📐 Vastu Optimization\\n- Sunlight optimization\\n- Ventilation analysis\\n- Directional planning\\n- Cultural design integration\\n\\n### 🖼️ Image Understanding\\n- Upload plot drawings\\n- Analyze sketches and layouts\\n- Extract design inspiration\\n- Redesign based on references\\n\\n### 📊 Real-Time Features\\n- Instant visual previews\\n- Interactive design canvas\\n- Blueprint visual effects\\n- Cinematic transitions\\n\\n## 🛠️ Tech Stack\\n\\n### Frontend\\n- **Next.js 14** - React framework\\n- **TypeScript** - Type safety\\n- **Tailwind CSS** - Styling with luxury theme\\n- **Framer Motion** - Animations and interactions\\n- **Three.js** - 3D visualization\\n- **React Three Fiber** - 3D in React\\n- **Lucide React** - Icons\\n\\n### Backend & Services\\n- **Next.js API Routes** - Backend\\n- **OpenAI API** - Advanced AI capabilities\\n- **Anthropic Claude** - Alternative AI model\\n- **Supabase** - Database & authentication\\n- **Sharp** - Image processing\\n\\n### Development\\n- **ESLint** - Code quality\\n- **Prettier** - Code formatting\\n- **Jest** - Testing\\n\n## 📦 Getting Started\\n\\n### Prerequisites\\n- Node.js 18+\\n- npm or pnpm\\n- Git\\n\n### Installation\\n\\n1. **Clone the repository:**\\n```bash\\ngit clone https://github.com/carrunpurohit-png/ai-architecture-design.git\\ncd ai-architecture-design\\n```\\n\n2. **Install dependencies:**\\n```bash\\nnpm install\\n# or\\npnpm install\\n```\\n\n3. **Set up environment variables:**\\n```bash\\ncp .env.example .env.local\\n```\\n\n4. **Add your API keys to `.env.local`:**\\n```\\nNEXT_PUBLIC_OPENAI_API_KEY=your_key_here\\nNEXT_PUBLIC_ANTHROPIC_API_KEY=your_key_here\\nNEXT_PUBLIC_SUPABASE_URL=your_url_here\\nNEXT_PUBLIC_SUPABASE_ANON_KEY=your_key_here\\nNEXTAUTH_SECRET=your_secret_here\\n```\\n\n5. **Run development server:**\\n```bash\\nnpm run dev\\n```\\n\n6. **Open http://localhost:3000 in your browser**\\n\n## 📝 Project Structure\\n\n```\nai-architecture-design/\n├── src/\n│   ├── app/\n│   │   ├── layout.tsx              # Root layout\n│   │   ├── globals.css             # Global styles\n│   │   ├── page.tsx                # Landing page\n│   │   └── dashboard/\n│   │       └── page.tsx            # Dashboard\n│   ├── components/                 # React components\n│   ├── lib/                        # Utilities & helpers\n│   └── api/                        # API routes\n├── public/                         # Static files\n├── package.json                    # Dependencies\n├── tailwind.config.ts              # Tailwind config\n├── tsconfig.json                   # TypeScript config\n├── next.config.js                  # Next.js config\n└── README.md                       # This file\n```\n\n## 🎨 Design System\\n\n### Colors\\n- **Gold**: #D4AF37 (Primary)\n- **Gold Light**: #E8C547 (Hover)\n- **Gold Dark**: #B8941E (Active)\n- **Platinum**: #E0E0E0 (Text)\n- **Dark BG**: #0A0A0A\n- **Dark Card**: #1A1A1A\n\n### Fonts\\n- **Serif**: Playfair Display (Headings)\n- **Sans**: Poppins (Body)\n\n## 📚 Available Scripts\\n\n- `npm run dev` - Start development server\n- `npm run build` - Build for production\n- `npm run start` - Start production server\n- `npm run lint` - Run ESLint\n- `npm run format` - Format code with Prettier\n- `npm run type-check` - Check TypeScript types\n\n## 🚀 Deployment\\n\n### Deploy to Vercel (Recommended)\n\n1. Push your code to GitHub\n2. Go to [vercel.com](https://vercel.com)\n3. Connect your GitHub repository\n4. Add environment variables\n5. Deploy!\n\n### Deploy to Other Platforms\n\n- **Netlify**: Follow their Next.js deployment guide\n- **AWS**: Use AWS Amplify or EC2\n- **Self-hosted**: Build with `npm run build` and run `npm start`\n\n## 🤝 Contributing\\n\nContributions are welcome! Please follow these steps:\n\n1. Fork the repository\n2. Create a feature branch (`git checkout -b feature/AmazingFeature`)\n3. Commit your changes (`git commit -m 'Add AmazingFeature'`)\n4. Push to the branch (`git push origin feature/AmazingFeature`)\n5. Open a Pull Request\n\n## 📄 License\\n\nThis project is licensed under the MIT License - see the LICENSE file for details.\n\n## 🙏 Acknowledgments\\n\n- Inspired by global luxury architecture and design trends\n- Powered by advanced AI models\n- Built with cutting-edge web technologies\n\n## 📞 Support\\n\nFor support, email support@aiarchitecture.com or open an issue on GitHub.\n\n---\n\n**Made with ❤️ by the AI Architecture Team**\n\"\n  }\n]"}

