{"content": "'use client'

import { useState } from 'react'
import { motion } from 'framer-motion'
import { Send, Paperclip, Plus } from 'lucide-react'

interface Message {
  id: string
  role: 'user' | 'assistant'
  content: string
  timestamp: Date
}

export default function ChatInterface() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: 'Hello! I\'m your AI Architect Guru. I can help you with architectural design, Vastu optimization, material recommendations, and much more. What would you like to create today?',
      timestamp: new Date(),
    },
  ])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!input.trim()) return

    // Add user message
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date(),
    }

    setMessages(prev => [...prev, userMessage])
    setInput('')
    setLoading(true)

    // Simulate AI response
    setTimeout(() => {
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: 'I understand you want to create an architectural design. Let me help you with that. Would you like to:\n\n1. Generate multiple design concepts\n2. Upload a plot/sketch for analysis\n3. Get Vastu optimization suggestions\n4. Explore specific architectural styles\n\nJust let me know your preference!',
        timestamp: new Date(),
      }
      setMessages(prev => [...prev, assistantMessage])
      setLoading(false)
    }, 1000)
  }

  return (
    <div className="flex flex-col h-screen bg-black">
      {/* Header */}
      <div className="border-b border-gold/20 bg-black/50 backdrop-blur-md p-6">
        <h2 className="text-2xl font-bold text-gold">AI Architect Guru</h2>
        <p className="text-platinum text-sm mt-1">Your intelligent design assistant</p>
      </div>

      {/* Messages Container */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {messages.map((message, index) => (
          <motion.div
            key={message.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1 }}
            className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-md lg:max-w-2xl rounded-lg p-4 ${
                message.role === 'user'
                  ? 'bg-gold text-black rounded-br-none'
                  : 'bg-dark-card border border-gold/30 text-platinum rounded-bl-none'
              }`}
            >
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{message.content}</p>
              <p className={`text-xs mt-2 ${message.role === 'user' ? 'text-black/50' : 'text-platinum/50'}`}>
                {message.timestamp.toLocaleTimeString()}
              </p>
            </div>
          </motion.div>
        ))}
        {loading && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="flex justify-start"
          >
            <div className="bg-dark-card border border-gold/30 rounded-lg p-4 rounded-bl-none">
              <div className="flex gap-2">
                <div className="w-2 h-2 bg-gold rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-gold rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                <div className="w-2 h-2 bg-gold rounded-full animate-bounce" style={{ animationDelay: '0.4s' }} />
              </div>
            </div>
          </motion.div>
        )}
      </div>

      {/* Input Area */}
      <div className="border-t border-gold/20 bg-black/50 backdrop-blur-md p-6">
        <form onSubmit={handleSendMessage} className="flex gap-4">
          <button
            type="button"
            className="p-3 rounded-lg border border-gold/30 hover:border-gold hover:bg-gold/10 transition-colors"
          >
            <Paperclip className="w-5 h-5 text-gold" />
          </button>
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask me about design, Vastu, materials, colors..."
            className="flex-1 bg-dark-card border border-gold/30 rounded-lg px-4 py-3 text-white placeholder-platinum/50 focus:outline-none focus:border-gold transition-colors"
          />
          <button
            type="submit"
            disabled={loading}
            className="p-3 rounded-lg bg-gold text-black hover:bg-gold-light transition-colors disabled:opacity-50"
          >
            <Send className="w-5 h-5" />
          </button>
        </form>
      </div>
    </div>
  )
}
