import { useState, useRef } from 'react'
import { motion } from 'framer-motion'
import { Upload, X, AlertCircle } from 'lucide-react'

interface UploadedFile {
  id: string
  name: string
  type: string
  preview: string
  analysis?: string
}

export default function ImageUploadSystem() {
  const [files, setFiles] = useState<UploadedFile[]>([])
  const [loading, setLoading] = useState(false)
  const [analysis, setAnalysis] = useState<string>('')
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const uploadedFiles = e.target.files
    if (!uploadedFiles) return

    Array.from(uploadedFiles).forEach(file => {
      const reader = new FileReader()
      reader.onload = (event) => {
        const newFile: UploadedFile = {
          id: Date.now().toString(),
          name: file.name,
          type: file.type,
          preview: event.target?.result as string,
        }
        setFiles(prev => [...prev, newFile])
      }
      reader.readAsDataURL(file)
    })
  }

  const handleAnalyze = async (fileId: string) => {
    setLoading(true)
    // Simulate AI analysis
    setTimeout(() => {
      setAnalysis(`AI Analysis Results:

✓ Plot Dimensions: 40ft x 60ft (2400 sq ft)
✓ Orientation: North-East facing (Vastu favorable)
✓ Sunlight: Good morning sunlight in east wing
✓ Ventilation: Optimal cross-ventilation possible
✓ Suggested Layout: 3-bedroom villa
✓ Vastu Score: 8.5/10

Recommendations:
• Master bedroom in SW corner
• Kitchen in SE corner
• Living area in NE corner
• Main entrance in E/N direction`)
      setLoading(false)
    }, 2000)
  }

  const removeFile = (id: string) => {
    setFiles(prev => prev.filter(f => f.id !== id))
  }

  return (
    <div className="w-full max-w-4xl mx-auto p-6">
      <div className="bg-dark-card border-2 border-dashed border-gold/30 rounded-xl p-8">
        <div className="text-center mb-6">
          <Upload className="w-12 h-12 text-gold mx-auto mb-3" />
          <h3 className="text-2xl font-bold mb-2">Upload Plot or Sketch</h3>
          <p className="text-platinum">Drag and drop or click to upload your architectural drawings</p>
        </div>

        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept="image/*,.pdf"
          onChange={handleFileUpload}
          className="hidden"
        />

        <button
          onClick={() => fileInputRef.current?.click()}
          className="w-full py-3 rounded-lg border-2 border-gold text-gold hover:bg-gold/10 transition-colors font-semibold"
        >
          Choose Files
        </button>
      </div>

      {/* Uploaded Files */}
      {files.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mt-8"
        >
          <h4 className="text-xl font-bold mb-4">Uploaded Files</h4>
          <div className="space-y-4">
            {files.map(file => (
              <div key={file.id} className="bg-dark-card border border-gold/20 rounded-lg p-4">
                <div className="flex gap-4">
                  <img src={file.preview} alt={file.name} className="w-24 h-24 object-cover rounded-lg" />
                  <div className="flex-1">
                    <p className="font-semibold mb-2">{file.name}</p>
                    <button
                      onClick={() => handleAnalyze(file.id)}
                      disabled={loading}
                      className="px-4 py-2 bg-gold text-black rounded-lg hover:bg-gold-light transition-colors disabled:opacity-50"
                    >
                      {loading ? 'Analyzing...' : 'Analyze with AI'}
                    </button>
                    <button
                      onClick={() => removeFile(file.id)}
                      className="ml-2 p-2 text-platinum hover:text-red-400 transition-colors"
                    >
                      <X className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </motion.div>
      )}

      {/* Analysis Results */}
      {analysis && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mt-8 bg-gold/5 border border-gold/30 rounded-lg p-6"
        >
          <h4 className="text-xl font-bold mb-4 text-gold">Analysis Results</h4>
          <pre className="text-platinum whitespace-pre-wrap text-sm leading-relaxed">{analysis}</pre>
        </motion.div>
      )}
    </div>
  )
}
