{"content": "import { NextResponse } from 'next/server'

interface User {
  id: string
  email: string
  name: string
  createdAt: string
}

interface Project {
  id: string
  userId: string
  name: string
  description: string
  concepts: number
  vastuScore: number
  createdAt: string
  updatedAt: string
}

// Mock database
const users: Map<string, User> = new Map()
const projects: Map<string, Project> = new Map()

export async function POST(req: Request) {
  try {
    const { action, email, name, userId, projectData } = await req.json()

    if (action === 'register') {
      const newUser: User = {
        id: `user-${Date.now()}`,
        email,
        name,
        createdAt: new Date().toISOString(),
      }
      users.set(newUser.id, newUser)
      return NextResponse.json({ success: true, user: newUser })
    }

    if (action === 'login') {
      const user = Array.from(users.values()).find(u => u.email === email)
      if (user) {
        return NextResponse.json({ success: true, user })
      }
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    if (action === 'createProject') {
      const newProject: Project = {
        id: `project-${Date.now()}`,
        userId,
        name: projectData.name,
        description: projectData.description,
        concepts: 0,
        vastuScore: 0,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      }
      projects.set(newProject.id, newProject)
      return NextResponse.json({ success: true, project: newProject })
    }

    if (action === 'getProjects') {
      const userProjects = Array.from(projects.values()).filter(p => p.userId === userId)
      return NextResponse.json({ success: true, projects: userProjects })
    }

    return NextResponse.json({ error: 'Invalid action' }, { status: 400 })
  } catch (error) {
    return NextResponse.json(
      { error: 'Database operation failed' },
      { status: 500 }
    )
  }
}
